set -eu
sudo docker exec quickreels-api-1 node -e 'const {PrismaClient}=require("@prisma/client"); const {loadEnv}=require("./dist/config/env"); const {miniAppEnvironment}=require("./dist/config/mini-apps"); (async()=>{ const db=new PrismaClient({datasources:{db:{url:miniAppEnvironment(loadEnv(),"talereels").DATABASE_URL}}}); try { const rows=await db.appEntryAdPolicy.findMany({select:{releaseId:true,enabled:true,mode:true,version:true},orderBy:{updatedAt:"desc"}}); console.log(JSON.stringify({miniApp:"talereels",policies:rows})); } finally { await db.$disconnect(); } })().catch(error=>{console.error(error.message);process.exit(1)})'
